/* Fixed sampled artwork, captured from the approved Mac rendering on 2026-09-14.
 * This contains pixel runs, not fonts: Windows, macOS and mobile all sample the
 * same ink in the same order. No installed font or canvas text fallback is used.
 * Ink: 1600px rows; publication: original 1400 x 1400 engraving alpha mask.
 */
(() => {
  'use strict';
  const records={"galoisTitle":{"count":11708,"rle":""},"galoisDates":{"count":2734,"rle":""},"outro":{"count":68507,"rle":""},"publication":{"count":1960000,"rle":""}};
  const cache=new Map();
  function unpack(name,alpha){
    if(cache.has(name))return cache.get(name);
    const record=records[name];
    if(!record)throw new Error('Missing fixed opening artwork: '+name);
    const bytes=Uint8Array.from(atob(record.rle),ch=>ch.charCodeAt(0));
    let at=0,used=0,position=0;
    const value=()=>{let n=0,shift=0,byte;do{if(at>=bytes.length||shift>28)throw new Error('Invalid fixed opening artwork');byte=bytes[at++];n|=(byte&127)<<shift;shift+=7;}while(byte&128);return n>>>0;};
    const result=alpha?new Uint8Array(record.count):new Uint32Array(record.count);
    while(at<bytes.length){
      if(alpha){const length=value(),ink=bytes[at++];if(!length||ink===undefined||used+length>result.length)throw new Error('Invalid opening alpha runs');result.fill(ink,used,used+length);used+=length;}
      else{position+=value();const length=value();if(!length||used+length>result.length)throw new Error('Invalid opening ink runs');for(let i=0;i<length;i++)result[used++]=position++;}
    }
    if(used!==result.length)throw new Error('Incomplete fixed opening artwork');
    cache.set(name,result);return result;
  }
  window.CourseOpeningLetteringData=Object.freeze({
    pixels(name){if(name==='publication')throw new Error('Publication requires alpha data');return unpack(name,false);},
    publicationAlpha(){return unpack('publication',true);},
    source:'approved-mac-20260914'
  });
})();
